// Bundles the Forge Harness API + engine into a single self-contained ESM
// file for the Windows installer. better-sqlite3 stays external (native).
import { build } from "esbuild";
import { fileURLToPath } from "node:url";
import path from "node:path";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const result = await build({
  entryPoints: [path.join(root, "services/api/src/index.ts")],
  bundle: true,
  platform: "node",
  target: "node20",
  format: "cjs",
  outfile: path.join(root, "installer/staging/app/bundle.cjs"),
  sourcemap: false,
  minify: false,
  banner: {
    js: `// Forge Harness — bundled single-file server (generated by scripts/build-bundle.mjs)`,
  },
  external: [
    "better-sqlite3",
    "bindings",
    "file-uri-to-path",
    "prebuild-install",
  ],
  logLevel: "info",
});

console.log("bundle complete");
void result;
